<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';import {useBusinessStore,businessApi} from '../stores/business';import {switchEdition} from '../auth/bootstrap';import type {Target} from '@shared/labops-targets.js';
const business=useBusinessStore(),emit=defineEmits<{logout:[];navigate:[Target]}>(),theme=ref(localStorage.getItem('labops.theme')||'auto'),error=ref(''),busy=ref(false),preference=ref<{enabled:boolean;quietStart:string;quietEnd:string;maxPerDay:number;maxPerEvent:number;minIntervalMinutes:number;categories:string[]}>();
const media=matchMedia('(prefers-color-scheme: dark)');
function systemTheme(){if(theme.value==='auto')document.documentElement.dataset.theme=media.matches?'dark':'light';}media.addEventListener('change',systemTheme);onUnmounted(()=>media.removeEventListener('change',systemTheme));
function applyTheme(){localStorage.setItem('labops.theme',theme.value);document.documentElement.dataset.theme=theme.value==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme.value;}
onMounted(async()=>{try{preference.value=(await businessApi<{preference:typeof preference.value}>('proxy/reminder-preferences')).preference;}catch(e){error.value=(e as Error).message;}});
async function save(){if(!preference.value||busy.value)return;busy.value=true;try{await businessApi('proxy/reminder-preferences',{...preference.value,scopeKey:business.scopeKey});error.value='本人提醒偏好已保存到主系统';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section class="mobile-section"><h2>{{business.profile?.username}}</h2><p>主系统真实身份：{{business.profile?.identity==='admin'?'管理员':'志愿者'}}{{business.profile?.className?' · '+business.profile.className:''}}</p><p>登录、业务权限和数据来自主系统。</p></section><section class="mobile-section"><h3>界面</h3><label>主题<select v-model="theme" @change="applyTheme"><option value="auto">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label><button @click="switchEdition('desktop',{view:'profile'})">使用桌面版（记住 7 天）</button></section><form v-if="preference" class="mobile-section mobile-form" @submit.prevent="save"><h3>本人站内提醒偏好</h3><label class="mobile-check"><input v-model="preference.enabled" type="checkbox">启用站内提醒</label><label>静默开始<input v-model="preference.quietStart" type="time"></label><label>静默结束<input v-model="preference.quietEnd" type="time"></label><label>每日上限<input v-model.number="preference.maxPerDay" type="number" min="1" max="50"></label><label>同一依据最多提醒次数<input v-model.number="preference.maxPerEvent" type="number" min="1" max="20"></label><label>最短间隔（分钟）<input v-model.number="preference.minIntervalMinutes" type="number" min="0" max="1440"></label><button :disabled="busy">保存本人偏好</button><button type="button" @click="emit('navigate',{view:'automation'})">设置模板分类与规则</button></form><p v-if="error" role="status">{{error}}</p><section class="mobile-section"><h3>帮助与安装</h3><p>使用浏览器菜单“添加到主屏幕”可保留独立移动端入口。站内提醒以服务端记录为准，当前没有系统推送能力。</p><p>离线时保留当前输入；恢复后刷新会话或同一方案编号。保存失败时先保留回答，不会自动重发或重复办理。</p><p>聊天会话只查询；正式办理请新建工作会话或进入实验室工作台。删除对话不撤销已提交业务。</p><p>LabOps 0.6.0 · Asia/Shanghai</p></section><button class="mobile-danger" @click="emit('logout')">退出登录</button></template>
